const a={back:"Atrás",continue:"Continuar",step_of:"{current} de {total}",welcome:{title:"Bienvenido",lede:"Configuramos tu asistente aquí mismo, en la aplicación: una clave de API, una suscripción para tus agentes y tu palabra de activación. Después, una breve visita te enseña la aplicación.",language:"Idioma",lang_en:"English",lang_de:"Deutsch",lang_es:"Español",start:"Empezar"},keys:{title:"Añade una clave de API",lede:"Tu asistente necesita una clave de IA para pensar y hablar; sin ella, el chat y la voz siguen apagados. Esta es la página Claves API: pega una clave en la tarjeta de un proveedor y guárdala. Con OpenAI o Gemini basta una sola clave para la voz en directo.",waiting:"Esperando una clave…",connecting:"Activando todo…",connected:"Conectado: {provider}.",present:"Hay una clave guardada. Puedes continuar.",partial:"Algunas partes no cambiaron ({parts}). Puedes arreglarlo más tarde en esta página.",security:"Las claves se guardan en el llavero de tu sistema y solo van al proveedor que elegiste.",later:"Añadiré una clave más tarde"},subscriptions:{title:"Conecta una suscripción para tus agentes",lede:"Esta es la pestaña Agentes. Inicia sesión con una suscripción que ya pagas. Te recomendamos Claude (Pro o Max) o ChatGPT (Codex). Pulsa Connect en su fila; tu navegador se abre una vez.",waiting:"Aún no hay ninguna suscripción conectada…",connected:"Conectado: {names}.",why:"Una suscripción tiene un precio mensual fijo, así las tareas grandes de tus agentes no se cobran por llamada a tu clave de API.",later:"Conectaré una más tarde"},permissions:{title:"Permitir acceso en este Mac",lede:"Estos son los permisos del Mac. Permite los que quieras; cada fila se actualiza sola.",note:"Puedes volver a ellos cuando quieras en Ajustes. El reinicio final los aplica."},voice:{title:"Elige tu palabra de activación",lede:"Escribe aquí tu palabra después de «Hey» y guárdala. La palabra también será el nombre de tu asistente. ¿Sin palabra? El atajo de llamada funciona siempre.",on:"«{phrase}» está activada. Dila cuando quieras.",off:"Aún no hay palabra de activación. Mientras tanto funciona el atajo de llamada.",later:"Omitir, usaré el atajo de llamada"},ready:{title:"Todo listo",lede:"Esto es lo que está configurado. Ahora, una breve visita te enseña la aplicación.",row_brain:"Cerebro",row_agents:"Agentes",row_voice:"Activación",no_subscription:"Sin suscripción",no_key:"Sin clave todavía",shortcut:"Atajo de llamada",autostart:"Iniciar al entrar en la sesión",no_key_note:"Sin clave, el chat y la voz siguen apagados hasta que añadas una en la página Claves API.",preview_note:"Esto es una repetición, así que no se reinicia nada.",restart_note:"Al terminar la visita, la aplicación se reinicia una vez (unos diez segundos) para activarlo todo.",start:"Enséñame la aplicación"}},e={label:"Visita guiada",next:"Siguiente",finish:"Terminar",skip:"Saltar visita",step_of:"{current} de {total}",replay_title:"Configuración y visita guiada",replay_body:"Te guía de nuevo por la configuración (claves de API, suscripciones de agentes, palabra de activación) y luego por la visita breve de la aplicación. Nada se reinicia.",replay:"Repetir",steps:{voice:"Así hablas con {name}. Haz clic en la barra, di tu palabra de activación o pulsa tu atajo de llamada, y habla. La onda muestra quién está hablando.",new_chat:"¿Prefieres escribir? Empieza aquí un chat nuevo, por texto o por voz. Cada conversación queda en Chats recientes.",agents:"Los agentes son tu equipo: ayudantes que se encargan de trabajos grandes en segundo plano. Echemos un vistazo.",agents_world:"Este es el Verse, tus agentes trabajando. Haz clic en uno para chatear con él o darle una tarea. Siguiente te lleva de vuelta.",voice_hub:"En Voz tienes el dictado en cualquier aplicación, tu propia lista de palabras y atajos hablados.",artifacts:"Todo lo que {name} crea, desde páginas hasta imágenes e informes, se guarda en Artefactos.",ide:"El Agentic IDE ejecuta agentes de programación uno al lado del otro en terminales reales, sobre tus proyectos.",plugins:"Plugins, skills y MCP conectan a {name} con tus aplicaciones. El icono de la tienda, abajo, abre el Marketplace.",settings:"Aquí están los ajustes, las claves de API, los costes y tu perfil. Puedes repetir esta visita cuando quieras en Ajustes → Aplicación.",done:"Esa es la visita. Ya está todo listo: habla con {name} cuando quieras."}},n={first_run:a,app_tour:e};export{e as app_tour,n as default,a as first_run};
